using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.SqlClient;
using RepairCenter.Api.Data;
using RepairCenter.Api.Models;
using System.Data;
namespace RepairCenter.Api.Controllers;
[ApiController]
[Route("api/employees")]
public sealed class EmployeesController : ControllerBase
{
 private readonly SqlConnectionFactory _factory; public EmployeesController(SqlConnectionFactory factory)=>_factory=factory;
 [HttpGet] public async Task<IActionResult> GetAll([FromQuery]string? search){var rows=new List<object>();await using var c=_factory.Create();await c.OpenAsync();await using var cmd=c.CreateCommand();cmd.CommandText="SELECT e.EmployeeID,e.FullName,e.Phone,e.IsActive,ISNULL(STUFF((SELECT N', '+s.SpecializationName FROM dbo.Course_project_0502_EmployeeSpecializations es JOIN dbo.Course_project_0502_Specializations s ON s.SpecializationID=es.SpecializationID WHERE es.EmployeeID=e.EmployeeID FOR XML PATH(''),TYPE).value('.','NVARCHAR(MAX)'),1,2,N'') FROM dbo.Course_project_0502_Employees e WHERE @s IS NULL OR e.FullName LIKE @p OR e.Phone LIKE @p ORDER BY e.FullName";cmd.Parameters.Add("@s",SqlDbType.NVarChar,150).Value=string.IsNullOrWhiteSpace(search)?DBNull.Value:search.Trim();cmd.Parameters.Add("@p",SqlDbType.NVarChar,300).Value=string.IsNullOrWhiteSpace(search)?DBNull.Value:"%"+search.Trim()+"%";await using var r=await cmd.ExecuteReaderAsync();while(await r.ReadAsync())rows.Add(new{EmployeeID=r.GetInt32(0),FullName=r.GetString(1),Phone=r.GetString(2),IsActive=r.GetBoolean(3),Specializations=r.IsDBNull(4)?string.Empty:r.GetString(4)});return Ok(rows);}
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){await using var c=_factory.Create();await c.OpenAsync();await using var cmd=c.CreateCommand();cmd.CommandText="SELECT EmployeeID,FullName,Phone,IsActive FROM dbo.Course_project_0502_Employees WHERE EmployeeID=@id";cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;await using var r=await cmd.ExecuteReaderAsync();if(!await r.ReadAsync())return NotFound();return Ok(new{EmployeeID=r.GetInt32(0),FullName=r.GetString(1),Phone=r.GetString(2),IsActive=r.GetBoolean(3)});}
 [HttpPost] public async Task<IActionResult> Create(EmployeeRequest request){await using var c=_factory.Create();await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();try{int id;await using(var cmd=c.CreateCommand()){cmd.Transaction=tx;cmd.CommandText="INSERT INTO dbo.Course_project_0502_Employees(FullName,Phone,IsActive) OUTPUT INSERTED.EmployeeID VALUES(@n,@p,@a)";cmd.Parameters.Add("@n",SqlDbType.NVarChar,150).Value=request.FullName.Trim();cmd.Parameters.Add("@p",SqlDbType.NVarChar,20).Value=request.Phone.Trim();cmd.Parameters.Add("@a",SqlDbType.Bit).Value=request.IsActive;id=Convert.ToInt32(await cmd.ExecuteScalarAsync());}await SaveSpecs(c,tx,id,request.SpecializationIDs);await tx.CommitAsync();return CreatedAtAction(nameof(Get),new{id},new{EmployeeID=id});}catch{await tx.RollbackAsync();throw;}}
 [HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,EmployeeRequest request){await using var c=_factory.Create();await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();try{await using(var cmd=c.CreateCommand()){cmd.Transaction=tx;cmd.CommandText="UPDATE dbo.Course_project_0502_Employees SET FullName=@n,Phone=@p,IsActive=@a WHERE EmployeeID=@id";cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;cmd.Parameters.Add("@n",SqlDbType.NVarChar,150).Value=request.FullName.Trim();cmd.Parameters.Add("@p",SqlDbType.NVarChar,20).Value=request.Phone.Trim();cmd.Parameters.Add("@a",SqlDbType.Bit).Value=request.IsActive;if(await cmd.ExecuteNonQueryAsync()==0){await tx.RollbackAsync();return NotFound();}}await using(var cmd=c.CreateCommand()){cmd.Transaction=tx;cmd.CommandText="DELETE FROM dbo.Course_project_0502_EmployeeSpecializations WHERE EmployeeID=@id";cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;await cmd.ExecuteNonQueryAsync();}await SaveSpecs(c,tx,id,request.SpecializationIDs);await tx.CommitAsync();return NoContent();}catch{await tx.RollbackAsync();throw;}}
 [HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){try{await using var c=_factory.Create();await c.OpenAsync();await using var cmd=c.CreateCommand();cmd.CommandText="DELETE FROM dbo.Course_project_0502_Employees WHERE EmployeeID=@id";cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;return await cmd.ExecuteNonQueryAsync()==0?NotFound():NoContent();}catch(SqlException ex)when(ex.Number==547){return Conflict(new{message="Исполнитель связан с заказами или работами."});}}
 private static async Task SaveSpecs(SqlConnection c,SqlTransaction tx,int employeeId,IEnumerable<int> specs){foreach(int id in specs.Distinct()){await using var cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="INSERT INTO dbo.Course_project_0502_EmployeeSpecializations(EmployeeID,SpecializationID) SELECT @e,SpecializationID FROM dbo.Course_project_0502_Specializations WHERE SpecializationID=@s";cmd.Parameters.Add("@e",SqlDbType.Int).Value=employeeId;cmd.Parameters.Add("@s",SqlDbType.Int).Value=id;await cmd.ExecuteNonQueryAsync();}}
}
